fn single(x: &[i32], y: &[i32]) -> Vec<i32> {
    // Pre‐allocate enough space for both slices to avoid reallocations
    let mut result = Vec::with_capacity(x.len() + y.len());
    // Preserve the order of elements from the first slice
    result.extend_from_slice(x);
    // Then append the elements from the second slice
    result.extend_from_slice(y);
    result
}

